solution.pattern:
class MyClass:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        # または
        self.logger = logger  # モジュールレベルのloggerを使用

entries.alternative:
# 遅延初期化パターン
@property
def logger(self):
    if not hasattr(self, '_logger'):
        self._logger = logging.getLogger(__name__)
    return self._logger

code_example.find_insertion_point:
# 既存メソッドの後に挿入
marker = '    def existing_method('
lines = content.split('\n')
for i, line in enumerate(lines):
    if marker in line:
        # メソッド終了位置を検出
        method_indent = len(line) - len(line.lstrip())
        for j in range(i+1, len(lines)):
            current_indent = len(lines[j]) - len(lines[j].lstrip())
            if lines[j].strip() and current_indent <= method_indent:
                insert_pos = j
                break
